 "From port / airport": "Vanaf haven / luchthaven",
 "Delivery": "Levering",
 "Deliver to address": "Leveren op adres",
 "To port / airport": "Tot haven / luchthaven",
 "Receiver will collect": "Ontvanger haalt zelf op",
 "Sender &amp; receiver <span style=\"text-transform:none;letter-spacing:0;font-weight:500;color:var(--muted)\">(optional: fill in if you already know, it speeds up booking)</span>": "Afzender &amp; ontvanger <span style=\"text-transform:none;letter-spacing:0;font-weight:500;color:var(--muted)\">(optioneel: vul in als u het al weet, dat versnelt het boeken)</span>",
 "Sender name / company": "Naam / bedrijf afzender",
 "Who is sending the goods": "Wie verstuurt de goederen",
 "Receiver name / company": "Naam / bedrijf ontvanger",
 "Who will receive the goods": "Wie ontvangt de goederen",
